export const ALL_ICON_IDS = Object.keys(SYMBOL_VIEWBOXES);

/**
 * Injects the SVG sprites sheet into document.body if not already present.
 */
export function injectSvgSprites(): void {
  if (typeof document === 'undefined') {
    return;
  }
  if (document.getElementById('sprites')) {
    return;
  }

  const parser = new DOMParser();
  const doc = parser.parseFromString(SVG_SPRITES_HTML, 'image/svg+xml');
  const svgEl = doc.querySelector('svg');
  if (svgEl) {
    // Ensure display none
    svgEl.setAttribute('style', 'display: none;');
    svgEl.setAttribute('aria-hidden', 'true');
    const imported = document.importNode(svgEl, true);
    document.body.insertBefore(imported, document.body.firstChild);
  } else {
    const div = document.createElement('div');
    div.id = 'vantage-sprites-fallback';
    div.style.display = 'none';
    div.innerHTML = SVG_SPRITES_HTML;
    document.body.insertBefore(div, document.body.firstChild);
  }
}

/**
 * Renders an inline <svg> tag that references a symbol in the sprite sheet.
 *
 * @param iconId The ID of the symbol, e.g. "i-move", "key-move", or "#i-move"
 * @param className Optional CSS class name(s), e.g. "icon icon-move"
 * @returns HTML string for the icon <svg> element
 */
export function renderIconSvg(iconId: string, className?: string): string {
  const cleanId = iconId.startsWith('#') ? iconId.slice(1) : iconId;
  const viewBox = SYMBOL_VIEWBOXES[cleanId] ? ` viewBox="${SYMBOL_VIEWBOXES[cleanId]}"` : ' viewBox="0 0 500 500"';
  const cls = className ? ` class="${className}"` : ' class="icon"';
  return `<svg${cls}${viewBox} aria-hidden="true"><use href="#${cleanId}"></use></svg>`;
}
